297: uint32_t TgcReadUplink::_isolateBitsForRead(uint32_t value, uint32_t bitWidth, uint8_t bitOffset) {
298:     // Patched: safe mask generation
299:     uint64_t bitMask = ((1ULL << bitWidth) - 1ULL);
300:     if (bitWidth >= 32) bitMask = 0xFFFFFFFFULL;
301:     bitMask <<= bitOffset;
302:     return static_cast<uint32_t>((value & bitMask) >> bitOffset);
303: }
