305: // Takes and old value and replaces the specified bits defined by value, bitWidth and bitOffset.
306: uint32_t TgcReadUplink::_isolateBitsForWrite(uint32_t value, uint32_t bitWidth, uint8_t bitOffset, uint32_t oldValue) {
307:     // Patched: safe mask generation
308:     uint64_t bitMask = ((1ULL << bitWidth) - 1ULL);
309:     if (bitWidth >= 32) bitMask = 0xFFFFFFFFULL;
310:     bitMask <<= bitOffset;
311:     return static_cast<uint32_t>((oldValue & ~bitMask) | ((static_cast<uint64_t>(value) << bitOffset) & bitMask));

