154: uint32_t ReadPRBS::_isolateBitsForWrite(uint32_t value, uint32_t bitWidth, uint8_t bitOffset, uint32_t oldValue) {
155:     const uint32_t mask = make_mask(bitWidth, bitOffset);
156:     // Evita overflow al desplazar y recorta al mask
157:     const uint32_t shifted = (bitOffset == 0) ? value : (value << bitOffset);
158:     return (oldValue & ~mask) | (shifted & mask);
159: }

